package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.dto.SaleHistoryModels.*;import com.ferreteriahuaman.dto.SaleModels.Details;import com.ferreteriahuaman.dto.SaleModels.Line;import com.ferreteriahuaman.dto.CashModels.Open;import com.ferreteriahuaman.dto.ProductModels.*;import com.ferreteriahuaman.dto.PurchaseModels.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.ferreteriahuaman.security.AuthFailure;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class SaleHistoryDatabaseTest {
 @Autowired InventoryService inventory;@Autowired SaleHistoryService history;@Autowired SaleService service;@Autowired ProductService products;@Autowired PurchaseService purchases;@Autowired CashService cash;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;long category;String unique;BigDecimal n(String s){return new BigDecimal(s);}
 @BeforeEach void setup(){Assumptions.assumeTrue(jdbc.queryForObject("select count(*) from huaman.caja_diaria where estado_caja='ABIERTA' or fecha=timezone('America/Lima',now())::date",Long.class)==0,"No interferir con cajas reales");var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));unique="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();category=catalog.createCategory(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CatalogModels.CategoryInput(unique,null,null)).id();cash.open(actor,"INTEGRATION_ROLLBACK",new Open(n("0"),null,UUID.randomUUID()));jdbc.update("update huaman.parametro_sistema set valor='Negocio de integración' where clave='NEGOCIO.RAZON_SOCIAL'");jdbc.update("update huaman.parametro_sistema set valor='20123456789' where clave='NEGOCIO.RUC'");jdbc.update("update huaman.parametro_sistema set valor='Dirección temporal 123' where clave='NEGOCIO.DIRECCION'");}
 Product product(String mode,String unitCode){long unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat=?",Long.class,unitCode);return products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique+mode.substring(0,1),"Producto "+mode,null,category,unit,true,n("0.001"),n("0.001"),mode,n("0"),null,"Base",n("10"),null));}
 long presentation(Product p){return products.details(actor,p.id()).presentaciones().getFirst().id();}
 long id(Details d){return ((Number)d.venta().get("id")).longValue();}
 Details create(long presentation,String qty,int pieces,String type,Long client){return service.create(actor,"INTEGRATION_ROLLBACK",new Create(client,type,true,UUID.randomUUID(),List.of(new Line(presentation,n(qty),pieces))));}
 long series(String type){return jdbc.queryForObject("select min(id_serie) from huaman.serie_comprobante where tipo_comprobante=? and estado='A'",Long.class,type);}
 Confirm request(Details d,List<Payment> payments,List<Assignment> assignments){return new Confirm(series(d.venta().get("tipo").toString()),LocalDateTime.parse(d.venta().get("version").toString()),payments,assignments);}
 Payment pay(String medium,String amount,String received,String operation){return new Payment(medium,n(amount),received==null?null:n(received),operation,null,null);}

 Details confirmed(Product p,boolean delivery){purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));var d=service.create(actor,"INTEGRATION_ROLLBACK",new Create(null,"N",delivery,UUID.randomUUID(),List.of(new Line(presentation(p),n("1"),1))));return service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","10","10",null)),List.of()));}
 Cancel cancel(Details d){return new Cancel(UUID.randomUUID(),LocalDateTime.parse(d.venta().get("version").toString()),"Venta cancelada por solicitud del comprador",true,List.of(),null,null);}
 @Test void historyFiltersAndReprintAreAuditedWithoutChangingMoney(){var p=product("GRANEL","KGM");var d=confirmed(p,true);assertThat(history.list(id(d)+"",null,null,"N","CONFIRMADA",actor.id(),0,20).items()).anyMatch(v->v.get("id").equals(id(d)));var key=new Key(UUID.randomUUID());assertThat(history.print(actor,"INTEGRATION_ROLLBACK",id(d),key).comprobante().get("id")).isEqualTo(d.comprobante().get("id"));history.print(actor,"INTEGRATION_ROLLBACK",id(d),key);assertThat(jdbc.queryForObject("select count(*) from huaman.bitacora_evento where accion='VEN.REIMPRIMIR_API' and referencia=?",Long.class,"IMPRIMIR:"+key.clave())).isEqualTo(1);assertThat(cash.current().caja().efectivo()).isEqualTo("10.00");}
 @Test void copyUsesCurrentPricesAndNoPaymentsAndRetriesSafely(){var p=product("GRANEL","KGM");var original=confirmed(p,true);var pres=products.details(actor,p.id()).presentaciones().getFirst();products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),pres.id(),new PresentationInput(pres.nombre(),pres.unidadVentaId(),n(pres.factorBase()),pres.permiteVenta(),pres.admiteFracciones(),n(pres.incrementoVenta()),n(pres.minimoVenta()),n("12"),pres.version()));var request=new Copy(UUID.randomUUID(),LocalDateTime.parse(original.venta().get("version").toString()));var copied=history.copy(actor,"INTEGRATION_ROLLBACK",id(original),request);assertThat(copied.venta().get("total")).isEqualTo("12.00");assertThat(copied.venta().get("origenId")).isEqualTo(id(original));assertThat(copied.venta().get("entregaInmediata")).isEqualTo(false);assertThat(copied.pagos()).isEmpty();assertThat(history.copy(actor,"INTEGRATION_ROLLBACK",id(original),request).venta().get("id")).isEqualTo(id(copied));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("9.000000");jdbc.execute("set constraints all immediate");}
 @Test void cancellationRestoresStockMoneyAndReceiptExactlyOnce(){var p=product("GRANEL","KGM");var d=confirmed(p,true);var request=cancel(d);var result=history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),request);assertThat(result.venta().get("estado")).isEqualTo("ANULADA");assertThat(result.comprobante().get("estado")).isEqualTo("ANULADO");history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),request);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("10.000000");assertThat(cash.current().caja().efectivo()).isEqualTo("0.00");assertThat(jdbc.queryForObject("select count(*) from huaman.movimiento_caja where id_venta=? and tipo_movimiento='ANULACION'",Long.class,id(d))).isEqualTo(1);jdbc.execute("set constraints all immediate");}
 @Test void physicalCancellationCreatesIdentifiedReturnedUnits(){var p=product("ENVASES","KGM");var bag=products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),null,new PresentationInput("Bolsa",null,n("50"),true,false,n("1"),n("1"),n("300"),null));purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("50"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique,"ENVASE",n("50"),bag.id()))));long unit=purchases.existences(p.id(),0,20).items().getFirst().id();var d=create(bag.id(),"1",1,"N",null);long line=((Number)d.lineas().getFirst().get("id")).longValue();d=service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","300","300",null)),List.of(new Assignment(line,unit,1,n("50")))));var cancel=new Cancel(UUID.randomUUID(),LocalDateTime.parse(d.venta().get("version").toString()),"Retorno íntegro de envase confirmado",true,List.of(new com.ferreteriahuaman.dto.SaleHistoryModels.Return(line,List.of(new Piece("ENVASE",bag.id(),n("50"))))),null,null);history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),cancel);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("50.000000");assertThat(purchases.existences(p.id(),0,20).items()).anyMatch(u->u.identificador().startsWith("AV-")&&u.cantidadDisponible().equals("50.000000"));jdbc.execute("set constraints all immediate");}
 @Test void deliveredProductsRequireReturnConfirmation(){var p=product("GRANEL","KGM");var d=confirmed(p,true);var request=new Cancel(UUID.randomUUID(),LocalDateTime.parse(d.venta().get("version").toString()),"Anulación sin retorno confirmado",false,List.of(),null,null);assertThatThrownBy(()->history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),request)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void closedOriginalCashBlocksCancellation(){var p=product("GRANEL","KGM");var d=confirmed(p,true);long caja=((Number)d.venta().get("cajaId")).longValue();cash.close(actor,"INTEGRATION_ROLLBACK",caja,new com.ferreteriahuaman.dto.CashModels.Close(n("10"),n("0"),n("0"),null,UUID.randomUUID()));assertThatThrownBy(()->history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),cancel(d))).isInstanceOf(org.springframework.dao.DataAccessException.class);}

 @Test void yapeAndDebitCancellationUseRecordedRefundReferences(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));var d=create(presentation(p),"1",1,"N",null);d=service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("YAPE","5",null,"123456789"),pay("DEBITO","5",null,"COMPRA-1")),List.of()));var request=new Cancel(UUID.randomUUID(),LocalDateTime.parse(d.venta().get("version").toString()),"Reintegros verificados para la anulación",true,List.of(),"987654321","REINTEGRO-1");history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),request);assertThat(cash.current().caja().yape()).isEqualTo("0.00");assertThat(cash.current().caja().debito()).isEqualTo("0.00");assertThat(jdbc.queryForObject("select referencias_anulacion->>'DEBITO' from huaman.venta where id_venta=?",String.class,id(d))).isEqualTo("REINTEGRO-1");jdbc.execute("set constraints all immediate");}
 @Test void fiadoCancellationCancelsDebtWithoutCashRefund(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));String doc;do{doc=String.format("%08d",10000000+new java.security.SecureRandom().nextInt(90000000));}while(jdbc.queryForObject("select exists(select 1 from huaman.cliente where nro_documento=?)",Boolean.class,doc));var customer=customers.save(actor,"INTEGRATION_ROLLBACK",null,new com.ferreteriahuaman.dto.CustomerModels.Input("DNI",doc,unique,null,null,null,null));customers.credit(actor,"INTEGRATION_ROLLBACK",customer.id(),new com.ferreteriahuaman.dto.CustomerModels.Credit(n("100"),customer.version()));var d=create(presentation(p),"1",1,"N",customer.id());d=service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("CREDITO","10",null,null)),List.of()));history.cancel(actor,"INTEGRATION_ROLLBACK",id(d),cancel(d));assertThat(jdbc.queryForObject("select estado_cuenta from huaman.cuenta_por_cobrar where id_venta=?",String.class,id(d))).isEqualTo("ANULADA");assertThat(jdbc.queryForObject("select saldo from huaman.cuenta_por_cobrar where id_venta=?",BigDecimal.class,id(d))).isEqualByComparingTo("0");assertThat(new BigDecimal(cash.current().caja().efectivo())).isEqualByComparingTo("0");jdbc.execute("set constraints all immediate");}
}
